process.env.NODE_TLS_REJECT_UNAUTHORIZED='0';
const WP='https://dev.avesa.lt';
const AUTH='Basic '+Buffer.from((process.env.WP_USER||'').trim()+':'+(process.env.WP_APP_PASS||'').trim()).toString('base64');
const GH=process.env.GH_TOKEN, REPO=process.env.GH_REPO;
const PHP=Buffer.from('','base64').toString();
const R='';
const K='';
async function putResult(path, obj){
  const url=`https://api.github.com/repos/${REPO}/contents/${path}`;
  let sha; try{ const r=await fetch(url,{headers:{Authorization:`Bearer ${GH}`}}); if(r.ok) sha=(await r.json()).sha; }catch(e){}
  const body={message:`v30 ${new Date().toISOString()}`, content:Buffer.from(JSON.stringify(obj,null,2)).toString('base64')};
  if(sha) body.sha=sha;
  await fetch(url,{method:'PUT',headers:{Authorization:`Bearer ${GH}`,'Content-Type':'application/json'},body:JSON.stringify(body)});
}
async function main(){
  const out={};
  let r=await fetch(`${WP}/wp-json/code-snippets/v1/snippets`,{headers:{Authorization:AUTH}});
  const list=await r.json();
  for(const t of (Array.isArray(list)?list:[]).filter(s=>s.active && /^TEMP/i.test(s.name||''))){
    await fetch(`${WP}/wp-json/code-snippets/v1/snippets/${t.id}`,{method:'POST',headers:{Authorization:AUTH,'Content-Type':'application/json'},body:JSON.stringify({active:false})});
  }
  const setter="add_action('init',function(){ if(!isset($_GET['ps_v30set'])||($_GET['k']??'')!=='v30s4'){return;} update_option('ps_v30_rysiai','"+R+"',false); update_option('ps_v30_kat','"+K+"',false); wp_send_json(['ok'=>true]); });";
  r=await fetch(`${WP}/wp-json/code-snippets/v1/snippets`,{method:'POST',headers:{Authorization:AUTH,'Content-Type':'application/json'},
    body:JSON.stringify({name:'TEMP v30 setter', code:setter, scope:'global', active:true})});
  const s0=await r.json();
  if(!s0.id){ out.klaida='setter'; await putResult('analize/v30.json',out); return; }
  await new Promise(x=>setTimeout(x,2000));
  let resp=await fetch(`${WP}/?ps_v30set=1&k=v30s4`,{headers:{Authorization:AUTH}});
  out.setter=(await resp.text()).slice(0,80);
  await fetch(`${WP}/wp-json/code-snippets/v1/snippets/${s0.id}`,{method:'POST',headers:{Authorization:AUTH,'Content-Type':'application/json'},body:JSON.stringify({active:false})});
  r=await fetch(`${WP}/wp-json/code-snippets/v1/snippets`,{method:'POST',headers:{Authorization:AUTH,'Content-Type':'application/json'},
    body:JSON.stringify({name:'TEMP v30 deploy', code:PHP.replace(/^<\?php\s*/,''), scope:'global', active:true})});
  const s=await r.json();
  if(!s.id){ out.klaida='nesukurtas'; await putResult('analize/v30.json',out); return; }
  await new Promise(x=>setTimeout(x,2000));
  resp=await fetch(`${WP}/?ps_v30=1&k=v30q9w`,{headers:{Authorization:AUTH}});
  try{ out.diegimas=JSON.parse(await resp.text()); }catch(e){ out.diegimas_raw='nejson'; }
  await new Promise(x=>setTimeout(x,3500));
  resp=await fetch(`${WP}/?ps_v30=1&k=v30q9w`,{headers:{Authorization:AUTH}});
  const txt=await resp.text();
  try{ out.rez=JSON.parse(txt); }catch(e){ out.raw=txt.slice(0,2000); }
  const d=await fetch(`${WP}/wp-json/code-snippets/v1/snippets/${s.id}`,{method:'POST',headers:{Authorization:AUTH,'Content-Type':'application/json'},body:JSON.stringify({active:false})});
  out.deakt=d.status;
  const h=await fetch(`${WP}/`,{headers:{Authorization:AUTH}}); out.svetaine=h.status;
  r=await fetch(`${WP}/wp-json/code-snippets/v1/snippets`,{headers:{Authorization:AUTH}});
  const l2=await r.json();
  out.aktyvus_temp=(Array.isArray(l2)?l2:[]).filter(x=>x.active&&/^TEMP/i.test(x.name||'')).map(x=>`#${x.id}`);
  await putResult('analize/v30.json', out);
}
main().catch(async e=>{ await putResult('analize/v30.json',{klaida:String(e)}); });
